-- Fix the existing browser signup, which inserts email/password_hash into SIGN_IN.
-- The current SIGN_IN.user_id is GENERATED BY DEFAULT AS IDENTITY; USER.user_id
-- has no generator. Create its matching USER row before the foreign-key check.
-- Run once as project owner. Existing account IDs and permissions are preserved.
begin;

lock table public."SIGN_IN", public."USER" in share row exclusive mode;

-- Advance the existing generator past IDs already in either table. Never rewind it.
select setval(
  'public."SIGN_IN_user_id_seq"'::regclass,
  greatest(
    coalesce((select max(user_id) from public."USER"), 1),
    coalesce((select max(user_id) from public."SIGN_IN"), 1),
    (select last_value from public."SIGN_IN_user_id_seq")
  ),
  true
);

create function public.ensure_user_for_sign_in()
returns trigger
language plpgsql
security invoker
set search_path = ''
as $$
begin
  if NEW.user_id is null then
    raise exception 'A generated user_id is required for signup.' using errcode = '23502';
  end if;
  if NEW.email is null or pg_catalog.btrim(NEW.email) = '' then
    raise exception 'An email is required for signup.' using errcode = '23514';
  end if;

  insert into public."USER" (user_id, email, display_name, created_at, updated_at)
  values (NEW.user_id, NEW.email, null, statement_timestamp(), statement_timestamp())
  on conflict (user_id) do nothing;

  -- Never attach credentials to an existing profile belonging to a different email.
  if not exists (
    select 1 from public."USER"
    where user_id = NEW.user_id and email = NEW.email
  ) then
    raise exception 'This user_id belongs to a different USER record.' using errcode = '23514';
  end if;

  return NEW;
end;
$$;

revoke all on function public.ensure_user_for_sign_in() from public;

create trigger sign_in_ensure_user
before insert on public."SIGN_IN"
for each row execute function public.ensure_user_for_sign_in();

comment on function public.ensure_user_for_sign_in() is
  'Create the matching USER row atomically for the existing SIGN_IN-first registration flow. Runs with caller permissions.';

commit;
